require __DIR__.'/app/bootstrap.php';$pending=$_SESSION['security_pending_2fa']??null;if(!$pending||empty($pending['user_id'])){header('Location: /login.php');exit;}$q=db()->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$q->execute([(int)$pending['user_id']]);$u=$q->fetch();if(!$u){unset($_SESSION['security_pending_2fa']);header('Location: /login.php');exit;}$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$code=trim((string)($_POST['code']??''));if(!security_verify_otp((int)$u['id'],$code,'login'))throw new RuntimeException('Invalid or expired verification code.');security_finalize_login($u,(string)($pending['redirect']??'/account.php'),(string)($pending['source']??'web'));}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Two-Factor Verification - <?=e(setting('site_name','ShahkotPK'))?></title><link rel="stylesheet" href="/assets/shahkotpk-auth-1.5.1.css?v=151"><style>body{display:grid;place-items:center;min-height:100vh;background:#eef3f9;font-family:system-ui}.otp{width:min(460px,92vw);background:#fff;border:1px solid #dfe6ef;border-radius:24px;padding:32px;box-shadow:0 20px 60px #10213a18}.otp input{font-size:28px;letter-spacing:8px;text-align:center;width:100%;padding:14px;border:1px solid #cfd8e6;border-radius:14px}.otp button{width:100%;margin-top:14px;padding:14px;border:0;border-radius:14px;background:#0f766e;color:#fff;font-weight:800}.err{padding:12px;background:#fee2e2;color:#991b1b;border-radius:12px}</style></head><body><main class="otp"><b>SHAHKOTPK SECURITY</b><h1>Verify your sign-in</h1><p>A 6-digit code was sent to <b><?=e(preg_replace('/(^.).*(@.*$)/','$1••••$2',(string)$u['email']))?></b>.</p><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" autocomplete="one-time-code" required autofocus><button>Verify & Continue</button></form></main></body></html>